javascript:(async()=>{const r=/https:\/\/lh\d\.googleusercontent\.com\/[^\s"'<>\\]+/g;const d=t=>t.replace(/\\\//g,"/").replace(/\\\\u003d|\\u003d/g,"=").replace(/\\\\u0026|\\u0026/g,"&").replace(/\\\\u003f|\\u003f/g,"?");const s=u=>{if(!u||!u.includes("googleusercontent.com"))return u;let t=u.replace(/\/s\d+(-[a-z]+)?\//g,"/s0/");t=t.replace(/=([swh]\d+[^&]*)$/,"=s0");if(!/=s0$/.test(t)&&!/=[swh]\d/.test(t))t+="=s0";return t};const h=async()=>{try{const n=await fetch(location.href,{credentials:"omit"});if(n.ok)return await n.text()}catch(e){}return document.documentElement.outerHTML};const html=await h();const urls=[...new Set((html.match(r)||[]).map(d).map(s).filter(Boolean))];if(!urls.length){alert("No photos found.");return}let i=1;for(const url of urls){const a=document.createElement("a");a.href=url;a.download="gbp-photo-"+("000"+i).slice(-3)+".jpg";document.body.appendChild(a);a.click();a.remove();i++}alert("Downloading "+urls.length+" photos.");})();
